+				     MDIO_AN_10GBT_CTRL_ADV2_5G,
+				     phy_ctrl);
+	if (ret < 0)
+		return ret;
+
+	ret = __genphy_config_aneg(phydev, ret);
+	if (ret < 0)
+		return ret;
+
+	mutex_unlock(&priv->shared_lock);
+	return ret;
